'use strict';
const storyId=new URLSearchParams(location.search).get('id');
const object=Hardware.find(d=>d.id===storyId);
const section=document.querySelector('#story-content');
if(!object){section.innerHTML='<section class="section not-found"><p class="eyebrow">OFF THE FLIGHT PATH</p><h1>That story isn’t in this archive.</h1><p>Choose a destination to find your next explorer.</p><div class="hero-actions"><a class="button outline" href="moon.html">Explore the Moon →</a><a class="button outline" href="mars.html">Explore Mars →</a></div></section>';document.querySelector('.related-section').hidden=true;}
else{
 const d=object,e=escapeHTML;document.title=d.name+' · After the Landing';document.body.classList.add(d.body.toLowerCase());document.querySelector(`nav [data-page="${d.body.toLowerCase()}"]`).setAttribute('aria-current','page');const firstPerson={
 'mars-09':['I was built for 90 days. My journey lasted nearly 15 years.','Opportunity landed in 2004 to study clues to ancient water. It explored for more than 14 years before contact was lost during a dust storm in 2018. NASA concluded the mission in 2019. Its tracks ended; the questions it helped answer did not.'],
 'mars-14':['They asked me to try five flights. I flew 72.','Ingenuity arrived attached to Perseverance. Its first flight in April 2021 proved that powered, controlled flight was possible in the thin Martian atmosphere. After its final flight in January 2024, damaged rotor blades ended its flying career. The idea it proved will travel much farther.'],
 'moon-18':['I have no battery. Yet Earth still listens for my reply.','A laser pulse leaves Earth, reaches an array of special mirrors on the Moon, and returns. Measuring the travel time reveals the distance. Apollo’s reflectors are a reminder that the simplest equipment can have an extraordinary scientific afterlife.'],
 'mars-08':['My wheels stopped. My discoveries kept going.','Spirit explored Gusev Crater, finding clues to water in the planet’s past. Trapped in soft soil, it eventually fell silent in 2010. Its discoveries helped scientists see that Mars had once been very different from the dry world we see today.'],
 'mars-12':['I stayed in one place and listened to a whole planet.','InSight did not need wheels. Its seismometer listened for marsquakes, while radio science helped reveal the interior. Dust eventually reduced its solar power. NASA ended the mission in 2022, but the measurements continue to help scientists study Mars.']};
 const narrative=firstPerson[d.id];const quote=narrative?narrative[0]:(d.operating?'My work is part of a story that is still unfolding.':'My journey brought me here. My story reached much farther.');
 section.innerHTML=`<section class="story-top section"><a class="breadcrumb" href="${d.body.toLowerCase()}.html">← BACK TO ${d.body==='Moon'?'THE MOON':'MARS'} COLLECTION</a><div class="story-title-row"><div><p class="eyebrow">${d.body.toUpperCase()} / ENTRY ${String(d.index).padStart(2,'0')} · ${e(d.category)}</p><h1>${e(d.name)}</h1><p class="story-subtitle">${e(d.mission)} <span>·</span> ${e(d.year)} <span>·</span> ${e(d.agency)}</p></div><button class="button outline story-save" data-save="${d.id}" aria-pressed="${storage.get().includes(d.id)}" aria-label="Save ${e(d.name)}">${storage.get().includes(d.id)?'♥ Story saved':'♡ Save this story'}</button></div><div class="story-layout"><figure class="story-figure">${imageMarkup(d)}<figcaption><strong>${e(d.displayCaption||d.imageTitle)}</strong><span>${e(d.imageContext?'Mission-context image; not an isolated photo of this object.':'NASA archive photograph, model, diagram, or illustration; see the original record for context.')}</span><a href="${e(d.imageSource)}" target="_blank" rel="noopener noreferrer">Image record & credit ↗</a><span>Credit: ${e(d.imageCredit)} · NASA ID ${e(d.imageNASAId)}</span></figcaption></figure><aside class="story-passport"><p class="eyebrow">MISSION PASSPORT</p><dl><div><dt>Object name</dt><dd>${e(d.name)}</dd></div><div><dt>Mission name</dt><dd>${e(d.mission)}</dd></div><div><dt>Mission year</dt><dd>${e(d.year)} <small>${d.body==='Moon'?'Surface deployment / mission range':'Arrival at Mars'}</small></dd></div><div><dt>Current status</dt><dd><span class="status-tag ${d.operating?'operating':''}">${d.operating?'Ongoing science / catalog active':'Retired / remains'}</span>${e(d.status)}</dd></div><div><dt>Where is it?</dt><dd>${e(d.location)}</dd></div></dl><p class="passport-note">Status follows the supplied catalog. Instrument status may differ from its parent mission. Follow NASA’s source for updates.</p></aside></div></section><section class="story-narrative section"><p class="eyebrow">IF THIS MACHINE COULD SPEAK</p><blockquote>“${e(quote)}”</blockquote><p class="imagined-note">An imagined voice, inspired by the mission’s history.</p><p class="narrative-copy">${e(narrative?narrative[1]:d.purpose+'. '+d.contribution+' '+d.matters)}</p></section><section class="section story-details"><div class="detail-heading"><p class="eyebrow">BEHIND THE MACHINE</p><h2>The science.<br>The sacrifice.<br>The legacy.</h2></div><div class="detail-list"><article><span>01</span><div><h3>What was its purpose?</h3><p>${e(d.purpose)}</p></div></article><article><span>02</span><div><h3>Why was it left behind or retired?</h3><p>${e(d.why)}</p></div></article><article><span>03</span><div><h3>What scientific contribution did it make?</h3><p>${e(d.contribution)}</p></div></article><article><span>04</span><div><h3>What is its current status?</h3><p>${e(d.status)}</p></div></article><article><span>05</span><div><h3>Why does it still matter today?</h3><p>${e(d.matters)}</p></div></article></div></section><section class="section story-sources"><p class="eyebrow">OFFICIAL NASA INFORMATION SOURCE</p><h2>Keep your curiosity going.</h2><p>Read the official information, inspect the original image, or explore more NASA photographs.</p><div class="story-source-links"><a class="button outline" href="${e(d.source)}" target="_blank" rel="noopener noreferrer">NASA information source ↗</a><a class="text-link" href="${e(d.imageSource)}" target="_blank" rel="noopener noreferrer">NASA image record ↗</a><a class="text-link" href="${e(d.archiveSearch)}" target="_blank" rel="noopener noreferrer">Search NASA photographs ↗</a></div>${d.notes.length?'<div class="catalog-notes"><strong>Catalog clarification</strong>'+d.notes.map(n=>'<p>'+e(n)+'</p>').join('')+'</div>':''}<details><summary>Original catalog entry & image context</summary><dl class="original-record">${Object.entries(d.original).map(([k,v])=>`<div><dt>${e(k.replaceAll('_',' '))}</dt><dd>${e(v)}</dd></div>`).join('')}</dl><p>${e(d.imageCoverage)}</p><p><strong>NASA image caption:</strong> ${e(d.imageDescription)}</p><p>Educational explanations and Moon mission years supplement the supplied CSV. Some entries overlap or describe multiple objects. Images may show equipment before launch or a related assembly rather than its present surface condition.</p></details></section><div class="story-nav section"><a href="${d.body.toLowerCase()}.html">← All ${d.body} stories</a><button id="share-story">Copy story link ↗</button></div>`;
 const related=Hardware.filter(x=>x.body===d.body&&x.id!==d.id);const index=related.findIndex(x=>x.index>d.index);const start=index<0?0:index;document.querySelector('#related').innerHTML=[...related.slice(start),...related.slice(0,start)].slice(0,3).map(card).join('');document.querySelector('#share-story').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);toast('Story link copied');}catch{toast('Copy this page’s address from your browser to share the story.');}});
}

